{"content": "/**
 * test-builds-first.test.ts — a script that runs tests which read `dist/` builds it
 * first.
 *
 * ## The failure this exists for
 *
 * `dist/` is this repository's build output and is gitignored, so a checkout does not
 * have it. Eight of the contract suites and four e2e suites read it — the generated
 * workflows, the release ruleset, the bundled tool servers — because the artifact is
 * what they are about.
 *
 * CI was never affected, which is the whole problem: `checks.from_pull_request` in
 * `.github/atomaton/config.yaml` runs `synth` before `test`, so the build happened in
 * the one place somebody was watching. An agent's run does not build: the runner runs
 * `environment.setup_commands` and nothing else, and that list is install-only.
 *
 * So `bun run test` was `0 fail` in CI and `59 fail` inside every agent's run, every
 * failure an `ENOENT` under `dist/`. Measured on a clean checkout:
 *
 *     rm -rf dist && bun run test
 *      1399 pass / 62 fail   (with ATOMATON_MACHINERY_ROOT set)
 *      1409 pass / 59 fail   (with it unset — the missing directory, not the variable)
 *
 * `bun run synth` takes 0.4s. An agent that does not already know to type it cannot
 * tell those 59 failures from ones its own change caused, which is the same damage the
 * hermetic-environment test beside this one exists for.
 *
 * ## Why the fix is here and not in `environment.setup_commands`
 *
 * Both were open, and this one is the one that works on the branch that changes it.
 * `setup_commands` is read from the DEFAULT BRANCH, so a command added there cannot be
 * exercised by the pull request that adds it — the run reviewing that pull request
 * still has the old list. A `pre<name>` script is in the tree under test, so the person
 * or agent reviewing it can reproduce the fix.
 *
 * It also covers every caller rather than the three jobs this repository happens to
 * have: `test` and `test:e2e` build before they read, whether the caller is an agent's
 * run, a laptop, or a check that runs the script directly. CI pays a second 0.4s build
 * for that, which is the cost of the two environments agreeing.
 *
 * ## What this holds
 *
 * 1. The behavioural half: `bun run test` and `bun run test:e2e` produce a `dist/` that
 *    was not there before, from a tree where it is missing.
 * 2. The ratchet: every `test*` script whose own files name a `dist/` path in code must
 *    build `dist/` first. A `.test.ts` added tomorrow that reads the artifact fails this
 *    rather than failing 20 minutes into somebody's run.
 *
 * ## What this cannot see
 *
 * A `dist/` path assembled from pieces (`join("dist", ...)`) reads the artifact without
 * naming it, and a file that reads `dist/` through a helper in another file is found
 * only by the name in the helper. Both directions are text scans, in the same shape as
 * `machinery-root.test.ts` beside it, and the limits are the same.
 */
import { describe, expect, test } from "bun:test";
import { spawnSync } from "node:child_process";
import { existsSync, readFileSync, readdirSync, rmSync, statSync } from "node:fs";
import { join } from "node:path";

/** Every script in package.json, by name. */
function scripts(): Record<string, string> {
  return (JSON.parse(readFileSync("package.json", "utf8")) as { scripts: Record<string, string> }).scripts;
}

/** The arguments to `bun test`, which are paths. The command itself is not. */
function pathsOf(command: string): string[] {
  return command
    .split(/\s+/)
    .slice(2)
    .filter((word) => word.startsWith("./") || word.startsWith("src/") || word.startsWith("tests/"));
}

/** Every `.ts` a path covers, at any depth. */
function typescriptFilesUnder(path: string): string[] {
  if (!existsSync(path)) return [];
  if (!statSync(path).isDirectory()) return path.endsWith(".ts") ? [path] : [];
  return readdirSync(path, { recursive: true })
    .map(String)
    .map((name) => join(path, name).replaceAll("\\", "/"))
    .filter((file) => file.endsWith(".ts") && statSync(file).isFile());
}

/**
 * The lines of a file that are code.
 *
 * Comments are left out because a file header explaining `dist/` is not a file reading
 * it — this file is one, and so are three of the suites it guards. A scan that counted
 * prose would demand a build for documentation about one.
 */
function codeLines(source: string): string {
  const kept: string[] = [];
  let inBlock = false;
  for (const line of source.split("\n")) {
    const trimmed = line.trim();
    if (inBlock) {
      if (trimmed.includes("*/")) inBlock = false;
      continue;
    }
    if (trimmed.startsWith("/*")) {
      if (!trimmed.includes("*/")) inBlock = true;
      continue;
    }
    if (trimmed.startsWith("*") || trimmed.startsWith("//")) continue;
    kept.push(line);
  }
  return kept.join("\n");
}

/** A `dist/...` path written out in code, rather than one assembled from pieces. */
const DIST_LITERAL = /["'`](dist\/[^"'`\n]*)["'`]/g;

/** The `test*` scripts, which are the ones whose files read what `synth` writes. */
function testScripts(): string[] {
  return Object.keys(scripts()).filter((name) => /^test(:|$)/.test(name));
}

describe("the scripts that run tests reading the build output", () => {
  /**
   * The ratchet, and the one that fails before the behavioural half can help: this
   * repository's `dist/` is gitignored, so a suite reading it is broken on every
   * checkout until something builds it.
   */
  test("build `dist/` before they run, whatever the caller set up", () => {
    const table = scripts();
    const offenders: string[] = [];

    for (const name of testScripts()) {
      const readers = new Set<string>();
      for (const file of pathsOf(table[name]!).flatMap(typescriptFilesUnder)) {
        if ([...codeLines(readFileSync(file, "utf8")).matchAll(DIST_LITERAL)].length > 0) readers.add(file);
      }
      if (readers.size === 0) continue;

      const hook = table[`pre${name}`];
      if (!hook || !hook.includes("synth")) {
        offenders.push(
          `${name} (reads dist/ in ${readers.size} file(s), e.g. ${[...readers][0]}): ` +
            (hook ? `\`pre${name}\` is \`${hook}\`, which does not run \`synth\`` : `no \`pre${name}\` script`),
        );
      }
    }

    expect(
      offenders,
      `\`bun test\` exits 0 on a path that does not exist, so a missing \`dist/\` is not an error ` +
        `there — it is 59 ENOENT failures in an agent's run, where nothing built it, while CI ` +
        `stays green because its check runs \`synth\` first. Add a \`pre<name>\` script running ` +
        `\`bun run synth\`:\n${offenders.join("\n")}`,
    ).toEqual([]);
  });

  /**
   * The scan above is a claim that these scripts' files really do read the artifact.
   * Without this the whole file passes on a tree where somebody has renamed the
   * directory, and passes for the wrong reason.
   */
  test("the scan is looking at files that name a dist/ path", () => {
    const readers = pathsOf(scripts().test!).flatMap(typescriptFilesUnder).filter((file) =>
      DIST_LITERAL.test(codeLines(readFileSync(file, "utf8"))),
    );
    expect(readers.length, "nothing under the `test` paths names a `dist/` path, so this checks nothing").toBeGreaterThan(0);
  });
});

describe("a cold tree, as an agent's run gets it", () => {
  /**
   * The behavioural half: from `dist/` deleted, the command CI runs leaves a build
   * behind. `bun run` runs `pretest` before `test`, which is the mechanism the ratchet
   * asserts and this measures.
   *
   * `ATOMATON_MACHINERY_ROOT` is deliberately not stripped. Inside an agent's run it is
   * set, and the reproduction that matters is the one with the run's own environment.
   */
  for (const name of ["test", "test:e2e"] as const) {
    test(`\`bun run ${name}\` builds dist/ from nothing`, () => {
      const hadDist = existsSync("dist");
      rmSync("dist", { recursive: true, force: true });
      expect(existsSync("dist"), "the precondition: no dist/ to be found").toBe(false);
      try {
        const r = spawnSync("bun", ["run", name], { encoding: "utf8", timeout: 600_000 });
